class CircleJig : EntityJig {
    Point3d _c; double _r = 1;
    public CircleJig(Point3d c) : base(new Circle(c, Vector3d.ZAxis, 1)) { _c = c; }
    protected override SamplerStatus Sampler(JigPrompts p) {
        var o = new JigPromptDistanceOptions("\nRadius: ") { BasePoint = _c, UseBasePoint = true };
        var r = p.AcquireDistance(o);
        if (r.Status != PromptStatus.OK) return SamplerStatus.Cancel;
        if (Math.Abs(r.Value - _r) < 1e-9) return SamplerStatus.NoChange;
        _r = r.Value; return SamplerStatus.OK;
    }
    protected override bool Update() { ((Circle)Entity).Radius = _r; return true; }
    public Entity Result => Entity;
}

